from taf.internal.robot_typecasts import time_to_seconds, to_boolean
from robot.api import logger


class BasicProceduresInterface(object):

    def block(self, dist_name, timeout=60):
        """Perform block procedure.

        :param string dist_name: block target object dist_name.
                                 Possible distanmes available in
                                 http://cebula.emea.nsn-net.net:8888/spec/admin-spec/wikis/admin-api-block-unblock
                                 From SBTS17A onwards it is recommended to use runtime view dist name
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        str(dist_name)
        self._api_client.execute_procedure("block", {"distName": dist_name}, timeout)

    def unblock(self, dist_name, timeout=60):
        """Preform unblock procedure.

        :param string dist_name: unblock target object dist_name.
                                 From SBTS17A onwards it is recommended to use runtime view dist name
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        str(dist_name)
        self._api_client.execute_procedure("unblock", {"distName": dist_name}, timeout)

    def collect_snapshot(
            self, target_file_name, coverage="Full", force=True, regexp_filter=None,
            reason=None, cells=None, timeout=360):
        """Collect Techrep snapshot.

        :param string target_file_name: target snapshot filename.
        :param string coverage: Snapshot coverage (Full or Minor)
        :param bool force: Force snapshot collection
        :param string filter: Snapshot filtering regexp (Optional)
        :param string reason: Snapshot reason (Optional)
        :param string cells: Comma-separated cell dist names (Optional)
        :param float timeout: Time to wait for positive procedure result
        
        """
        timeout = time_to_seconds(timeout)
        force = to_boolean(force)
        str(target_file_name)
        str(coverage)
        coverage = coverage.title()
        assert coverage in ("Full", "Minor")

        parameters = {
            "coverage": coverage,
            "force": "Yes" if force else "No",
        }

        if regexp_filter:
            str(regexp_filter)
            parameters["regExpFilter"] = regexp_filter
        if reason:
            str(reason)
            parameters["reason"] = reason
        if cells:
            str(cells)
            parameters["networkCellDNs"] = [dn.strip() for dn in cells.split(",")]

        self._api_client.execute_procedure("snapshot", parameters, timeout, output_file_name=target_file_name)

    def collect_im_snapshot(self, target_file_name, timeout=60):
        """Collect InfoModel snapshot.

        :param string target_file_name: target InfoModel snapshot filename.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        str(target_file_name)
        self._api_client.execute_procedure("imSnapshot", {}, timeout, output_file_name=target_file_name)

    def collect_infomodel_log_from_current_session(self, target_file_name, timeout=60):
        """Collect InfoModel log from current session.

        :param string target_file_name: target InfoModel snapshot filename.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        str(target_file_name)
        self._api_client.execute_infomodel_request("imsFromCurrentSession", {}, timeout, output_file_name=target_file_name)

    def reset_site(self, timeout=300):
        """Preform site reset procedure.

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_procedure("siteReset", {}, timeout)

    def reset_rat(self, rat, timeout=60):
        """Preform RAT reset procedure.

        :param string rat: RAT name (LTE, WCDMA or GSM).
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        assert rat in ("LTE", "WCDMA", "GSM")
        self._api_client.execute_procedure("ratReset", {"type": rat}, timeout)

    def enable_ethernet_port_security(self, timeout=60):
        """Enable ethernet port security.

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_procedure("changeEthernetPortSecurity", {"enableEthernetPortSec": True}, timeout)

    def disable_ethernet_port_security(self, timeout=60):
        """Disable ethernet port security.

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_procedure("changeEthernetPortSecurity", {"enableEthernetPortSec": False}, timeout)

    def get_mrbts_state(self, timeout=10):
        """Get MRBTS state.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: string
        :return: MRBTS state
        """
        timeout = time_to_seconds(timeout)
        return self._api_client.execute_infomodel_request("mrbtsMState", {}, timeout)

    def get_bts_info(self, timeout=10):
        """Get BTS info.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: string
        :return: BTS info
        """
        timeout = time_to_seconds(timeout)
        response = self._api_client.execute_customer_procedure("getBtsInformation", {}, timeout)
        return response["requestMessage"]
